.r4-home-collections{display:grid;grid-template-rows:1fr 1fr;gap:18px}.r4-collection{min-width:0;min-height:0;text-decoration:none;border:1px solid #E7E6DE;border-radius:13px;overflow:hidden;background:white;display:grid;grid-template-columns:1.1fr 1fr;align-items:stretch}.r4-collection>img{width:100%;height:100%;min-height:0;object-fit:cover;object-position:45% center}.r4-collection>div{padding:24px 18px;display:flex;flex-direction:column;justify-content:center;gap:8px}.r4-collection small{font-size:9px;color:#A0021F;letter-spacing:.12em}.r4-collection h2{font-size:23px;font-weight:600;letter-spacing:-.035em;margin:0}.r4-collection p{font-size:11px;color:#8B8B7D;line-height:1.8;margin:0}.r4-collection span{color:#A0021F;font-size:19px;margin-top:10px}.r4-collection:hover{border-color:#CDB6B3}.r4-collection:nth-child(2){background:#FCF7F4}
.r4-category-bar{margin:26px 0 33px;display:grid;grid-template-columns:repeat(8,minmax(0,1fr));background:#FFF;border:1px solid #E8E7DF;border-radius:10px;padding:16px 0}.r4-category-bar>a{display:flex;flex-direction:column;gap:5px;text-decoration:none;border-right:1px solid #EAEAE3;min-width:0;padding:1px 18px}.r4-category-bar>a:last-child{border:0}.r4-category-bar strong{font-size:13px;font-weight:600;white-space:nowrap}.r4-category-bar span{font-size:10px;line-height:1.5;color:#8D9285;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.r4-category-bar>a:hover strong{color:#A0021F}
.r4-today{display:grid;grid-template-columns:220px minmax(0,1fr);align-items:center;gap:22px;padding:23px 26px;background:#F9EDEF;border:1px solid #EFDDE0;border-radius:12px;margin-bottom:38px}.r4-today h2{font-size:22px;margin:7px 0;line-height:1.4;letter-spacing:-.025em}.r4-today p{font-size:11px;color:#946772;margin:0}.r4-today-picks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.r4-today-pick{padding:12px;background:#FFF;border:1px solid #F0E4E3;border-radius:8px;display:flex;align-items:center;gap:13px;min-width:0;text-decoration:none}.r4-today-pick[hidden]{display:none}.r4-today-pick>img{width:65px;height:67px;object-fit:cover;border-radius:5px;background:#FAFAF7;flex:none}.r4-today-pick>div{min-width:0;display:flex;flex-direction:column;gap:5px}.r4-today-pick [data-home-product-name]{font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.r4-today-pick [data-home-product-unit]{font-size:10px;color:#858B80}.r4-today-pick [data-home-product-price]{font-size:16px;font-weight:700;color:#A0021F}.r4-today-pick:hover{border-color:#B57080}
.r4-home-shelf{margin-bottom:40px}.r4-home-shelf:nth-of-type(2) .r4-section-heading h2{color:#A0021F}.r4-home-community{display:grid;grid-template-columns:1fr 1.1fr;min-height:245px;border-radius:14px;overflow:hidden;background:#8A142A;color:#FFF;margin:15px 0 34px}.r4-home-community>img{height:100%;max-height:310px;width:100%;object-fit:cover;object-position:center 45%}.r4-community-copy{padding:38px 40px;position:relative;overflow:hidden}.r4-community-copy>small{font-size:10px;color:#E9C4CB;letter-spacing:.14em}.r4-community-copy>h2{font-size:30px;font-weight:500;line-height:1.5;letter-spacing:.015em;margin:12px 0}.r4-community-copy>p{font-size:12px;color:#E5C6CB;line-height:1.8;max-width:88%;margin:0 0 21px}.r4-community-copy>a{color:#FFF;font-size:12px;text-underline-offset:6px}.r4-community-mascot{position:absolute;right:18px;bottom:-5px;width:106px;height:127px;object-fit:contain;filter:drop-shadow(0 5px 5px rgba(40,0,0,.12))}.r4-home-promises{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid #DEDfd7;padding:26px 0 0;gap:22px}.r4-home-promises>div{display:flex;gap:15px;align-items:flex-start}.r4-home-promises b{color:#A0021F;font-size:21px;line-height:1.2;font-weight:500}.r4-home-promises strong{display:block;font-size:12px;font-weight:600;margin-bottom:6px}.r4-home-promises small{display:block;font-size:10px;line-height:1.7;color:#8B9185}
@media(max-width:1200px){.r4-home-hero{grid-template-columns:minmax(0,1.8fr) minmax(250px,.9fr)}.r4-home-feature{min-height:420px}.r4-feature-copy{padding:32px}.r4-feature-copy h1{font-size:43px}.r4-collection{grid-template-columns:1fr 1.08fr}.r4-collection>div{padding:20px 14px}.r4-collection h2{font-size:21px}.r4-category-bar>a{padding:0 12px}.r4-today{grid-template-columns:180px minmax(0,1fr);gap:15px;padding:20px}.r4-today-pick{gap:8px;padding:10px}.r4-today-pick>img{width:48px;height:58px}.r4-today h2{font-size:20px}.r4-home-shelf .r4-product-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.r4-category-bar{grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.r4-category-bar>a:nth-child(4){border:0}}
@media(max-width:900px){.r4-home-hero{grid-template-columns:1fr}.r4-home-feature{min-height:390px}.r4-home-collections{grid-template-columns:1fr 1fr;grid-template-rows:auto}.r4-collection{height:165px}.r4-today{grid-template-columns:1fr}.r4-today>div:first-child{display:flex;align-items:baseline;gap:15px;flex-wrap:wrap}.r4-today>div:first-child h2{font-size:20px}.r4-home-community{grid-template-columns:1fr 1fr}.r4-community-copy{padding:28px}.r4-community-copy>h2{font-size:25px}.r4-community-mascot{width:80px;right:5px}.r4-home-promises{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.r4-home-shelf .r4-product-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.r4-home-intro{font-size:9px;gap:7px;margin-bottom:14px}.r4-home-intro strong{font-size:10px}.r4-home-feature{min-height:360px}.r4-feature-copy{padding:26px 23px;max-width:85%}.r4-feature-copy h1{font-size:36px}.r4-feature-copy>p{font-size:11px;line-height:1.85}.r4-home-feature>img{object-position:55% center;opacity:.83}.r4-home-feature:after{background:linear-gradient(90deg,rgba(14,33,26,.85),rgba(14,33,26,.42) 65%,rgba(14,33,26,.2))}.r4-feature-copy>p:first-child{font-size:9px}.r4-home-hero{gap:12px}.r4-home-collections{gap:12px}.r4-collection{height:188px;display:flex;flex-direction:column}.r4-collection>img{height:103px;flex:none;object-position:center 50%}.r4-collection>div{padding:12px;gap:3px}.r4-collection small{font-size:8px}.r4-collection h2{font-size:17px}.r4-collection p{font-size:9px}.r4-collection span{display:none}.r4-category-bar{margin:20px 0 24px;padding:14px 0;gap:15px}.r4-category-bar>a{padding:0 10px}.r4-category-bar strong{font-size:11px}.r4-category-bar span{font-size:8px}.r4-today{padding:15px;margin-bottom:28px}.r4-today>div:first-child{gap:6px}.r4-today-picks{gap:7px}.r4-today-pick{padding:8px;display:flex;flex-direction:column;gap:7px;align-items:flex-start}.r4-today-pick>img{width:100%;height:65px;object-fit:contain}.r4-today-pick [data-home-product-name]{font-size:10px;max-width:72px}.r4-today-pick [data-home-product-unit]{font-size:9px}.r4-today-pick [data-home-product-price]{font-size:14px}.r4-home-shelf{margin-bottom:30px}.r4-home-community{grid-template-columns:1fr}.r4-home-community>img{height:185px}.r4-community-copy{padding:27px 24px}.r4-community-copy>h2{font-size:26px}.r4-community-mascot{width:91px;height:110px}.r4-home-promises{gap:24px 12px}.r4-home-promises>div{gap:10px}.r4-home-promises b{font-size:18px}.r4-home-promises strong{font-size:11px}.r4-home-promises small{font-size:9px}}

List.css:
.r4-catalog-main{max-width:1280px;margin:0 auto;padding:24px 32px 58px;color:#202A25}
.r4-catalog-crumb{display:flex;align-items:center;gap:10px;margin-bottom:25px;font-size:12px;color:#778078}
.r4-catalog-crumb a{color:#667168;text-decoration:none}
.r4-catalog-crumb a:hover{color:#A0021F}
.r4-catalog-intro{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:26px}
.r4-catalog-kicker{margin:0 0 9px;color:#A0021F;font-size:11px;font-weight:700;letter-spacing:.17em}
.r4-catalog-title{display:flex;align-items:baseline;gap:15px;flex-wrap:wrap}
.r4-catalog-title h1{margin:0;font-size:32px;line-height:1.25;letter-spacing:-.035em;font-weight:750}
.r4-catalog-title>span{font-size:13px;color:#667168}
.r4-catalog-intro>span{max-width:270px;color:#667168;font-size:13px;line-height:1.7;text-align:right}
.r4-catalog-layout{display:grid;grid-template-columns:190px minmax(0,1fr);gap:28px;align-items:start}
.r4-catalog-categories{position:sticky;top:20px;padding:22px 16px 14px;border:1px solid #E7E5E0;border-radius:12px;background:#FFF}
.r4-catalog-categories h2{margin:0 10px 14px;font-size:14px;font-weight:750;color:#202A25}
.r4-catalog-categories>a{display:flex;align-items:center;justify-content:space-between;min-height:42px;box-sizing:border-box;padding:9px 10px;border-radius:7px;color:#59665C;text-decoration:none;font-size:14px;transition:background .15s,color .15s}
.r4-catalog-categories>a::after{content:'›';color:#A8B2A6;font-size:18px}
.r4-catalog-categories>a:hover{color:#A0021F;background:#FCF1F3}
.r4-catalog-categories>a[aria-current="page"]{color:#A0021F;background:#FCF1F3;font-weight:650}.r4-catalog-categories>a[aria-current="page"]::after{color:#A0021F}.r4-catalog-categories br{display:none}
.r4-catalog-results{min-width:0}
.r4-catalog-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px;padding-bottom:16px;border-bottom:1px solid #E7E5E0}
.r4-catalog-sort{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.r4-catalog-sort button{height:34px;padding:0 15px;border:1px solid transparent;border-radius:7px;background:transparent;color:#667168;font-family:inherit;font-weight:500;font-size:13px;cursor:pointer}
.r4-catalog-sort button[aria-pressed="true"]{border-color:#F1D9DE;background:#FCF1F3;color:#A0021F;font-weight:700}
.r4-catalog-sort button:hover{background:#FCF1F3;color:#A0021F}
.r4-catalog-toolbar>span{color:#778078;font-size:12px;white-space:nowrap}
.r4-catalog-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.r4-catalog-grid .r4-product-card{min-width:0;overflow:hidden;display:flex;flex-direction:column;border:1px solid #E7E5E0;border-radius:12px;background:#FFF;transition:border-color .16s,box-shadow .16s,transform .16s}
.r4-catalog-grid .r4-product-card:hover{border-color:#DFCDD0;box-shadow:0 7px 20px rgba(32,42,37,.045);transform:translateY(-2px)}
.r4-catalog-grid .r4-product-media{position:relative;display:block;aspect-ratio:1.08;background:#F7F7F4;overflow:hidden}
.r4-catalog-grid .r4-product-media img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .3s}
.r4-catalog-grid .r4-product-card:hover .r4-product-media img{transform:scale(1.035)}
.r4-catalog-stock{position:absolute;left:0;right:0;bottom:0;display:block;padding:9px;text-align:center;color:white;background:rgba(32,42,37,.72);font-size:12px}
.r4-catalog-grid .r4-product-body{display:flex;flex:1;flex-direction:column;gap:7px;padding:15px 14px 14px}
.r4-catalog-badges{display:flex;flex-wrap:wrap;gap:5px;min-height:18px;align-items:center}
.r4-catalog-badges>span{font-size:10px!important;line-height:17px!important;padding:0 5px!important;border-radius:3px!important;font-weight:500!important}
.r4-catalog-weight-badge{color:#5F6D60;background:#EEF3EA}
.r4-catalog-near-badge{color:#905E29;background:#F8F0E0}
.r4-catalog-grid .r4-product-name{overflow:hidden;color:#202A25;text-decoration:none;font-size:15px;font-weight:650;line-height:1.5;text-overflow:ellipsis;white-space:nowrap}
.r4-catalog-grid .r4-product-name:hover{color:#A0021F}
.r4-catalog-grid .r4-product-meta{overflow:hidden;color:#778078;font-size:11px;line-height:1.55;text-overflow:ellipsis;white-space:nowrap}
.r4-catalog-price-row{display:flex;align-items:baseline;gap:7px;margin-top:7px;flex-wrap:wrap}
.r4-catalog-grid .r4-price{color:#A0021F;font-family:Arial,'PingFang SC',sans-serif;font-size:23px;line-height:1.1;font-weight:700;letter-spacing:-.035em;font-variant-numeric:tabular-nums}
.r4-catalog-grid .r4-price>span{font-size:13px;margin-right:2px;letter-spacing:0}
.r4-catalog-reference{color:#98A095;font-size:11px;text-decoration:line-through}
.r4-catalog-grid .r4-product-actions{margin-top:auto;padding-top:6px}
.r4-catalog-grid .r4-product-actions>button{display:flex;align-items:center;justify-content:center;width:100%;height:34px;padding:0 10px;border:1px solid #DFE6DC;border-radius:6px;background:#FFF;color:#A0021F;font-family:inherit;font-weight:600;font-size:12px;cursor:pointer;transition:color .15s,background .15s,border-color .15s}
.r4-catalog-grid .r4-product-actions>button:hover{background:#A0021F;border-color:#A0021F;color:#FFF}
.r4-catalog-grid .r4-product-actions>button:disabled{background:#F3F5F0;border-color:#E7E5E0;color:#98A095;cursor:not-allowed}
.r4-catalog-grid .r4-product-unit{font-size:10px;color:#879182;line-height:1.5}
.r4-catalog-end{display:flex;justify-content:center;align-items:center;gap:15px;margin:30px 0 0;color:#879182;font-size:12px}
.r4-catalog-end::before,.r4-catalog-end::after{content:'';width:45px;height:1px;background:#E0E6DC}
@media(max-width:1180px){.r4-catalog-main{padding-right:28px;padding-left:28px}.r4-catalog-layout{grid-template-columns:168px minmax(0,1fr);gap:22px}.r4-catalog-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.r4-catalog-intro>span{max-width:240px}.r4-catalog-title h1{font-size:29px}}
@media(max-width:760px){.r4-catalog-main{padding:22px 18px 38px}.r4-catalog-crumb{margin-bottom:20px}.r4-catalog-intro{margin-bottom:20px}.r4-catalog-intro>span{display:none}.r4-catalog-title h1{font-size:26px}.r4-catalog-layout{grid-template-columns:minmax(0,1fr);gap:16px}.r4-catalog-categories{position:static;display:flex;gap:4px;overflow:auto;padding:8px;border-radius:9px;scrollbar-width:none}.r4-catalog-categories h2{display:none}.r4-catalog-categories>a{flex:none;white-space:nowrap;min-height:34px;padding:5px 10px;font-size:12px}.r4-catalog-categories>a::after{display:none}.r4-catalog-toolbar{padding-bottom:12px;margin-bottom:14px}.r4-catalog-toolbar>span{display:none}.r4-catalog-sort button{padding:0 11px}.r4-catalog-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.r4-catalog-grid .r4-product-body{padding:12px}.r4-catalog-grid .r4-product-name{font-size:14px}.r4-catalog-grid .r4-price{font-size:22px}}
@media(prefers-reduced-motion:reduce){.r4-catalog-grid .r4-product-card,.r4-catalog-grid .r4-product-media img{transition:none;transform:none!important}}

Detail.css:
.r4-detail-main{max-width:1280px;margin:0 auto;padding:24px 32px 58px;color:#202A25}
.r4-detail-crumb{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:24px;font-size:12px;color:#899087;line-height:1.6}
.r4-detail-crumb a{color:#667168;text-decoration:none}
.r4-detail-crumb a:hover{color:#A0021F}
.r4-detail-crumb>span:last-child{color:#202A25}
.r4-detail-product{display:grid;grid-template-columns:minmax(0,1.02fr) minmax(0,1fr);gap:44px;padding:30px;background:#FFF;border:1px solid #E7E5E0;border-radius:16px}
.r4-detail-gallery{min-width:0}
.r4-detail-image{position:relative;aspect-ratio:1;overflow:hidden;border-radius:11px;background:#F5F5F1}
.r4-detail-image img{display:block;width:100%;height:100%;object-fit:cover}
.r4-detail-image-badge{position:absolute;top:18px;left:18px;display:inline-flex;gap:7px;align-items:center;padding:7px 10px;border-radius:5px;background:rgba(255,255,255,.94);font-size:11px;font-weight:650;letter-spacing:.03em;color:#81162B}
.r4-detail-image-badge::before{content:'';width:5px;height:5px;border-radius:50%;background:#A0021F}
.r4-detail-image-note{margin:14px 0 0;color:#879182;font-size:11px;line-height:1.7}
.r4-detail-purchase{display:flex;flex-direction:column;gap:19px;min-width:0;padding:2px 0}
.r4-detail-eyebrow{display:flex;align-items:center;gap:8px;color:#81162B;font-size:11px;line-height:1.4;font-weight:600;letter-spacing:.06em}
.r4-detail-eyebrow>span{padding:4px 7px;background:#FCF1F3;border-radius:4px;letter-spacing:0;font-weight:500}
.r4-detail-purchase h1{margin:9px 0 10px;font-size:31px;font-weight:750;line-height:1.35;letter-spacing:-.035em}
.r4-detail-description{margin:0;color:#727B71;font-size:13px;line-height:1.8}
.r4-detail-pricing{display:flex;flex-direction:column;gap:10px;border-radius:10px;padding:18px 20px;background:#FCF1F3;border:1px solid #F2E5E7}
.r4-detail-price-line{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}
.r4-detail-price-label{font-size:12px;font-weight:600;color:#81162B}
.r4-detail-price{color:#A0021F;font-size:36px;line-height:1;font-family:Arial,'PingFang SC',sans-serif;font-weight:700;letter-spacing:-.045em;font-variant-numeric:tabular-nums}
.r4-detail-price>span{margin-right:3px;font-size:19px;letter-spacing:0}
.r4-detail-price-unit{font-size:12px;color:#7D716E}
.r4-detail-reference{color:#9F9390;font-size:12px;text-decoration:line-through}
.r4-detail-price-note{color:#94817F;font-size:11px;line-height:1.7}
.r4-detail-choice{margin:0;padding:0;border:0;min-width:0}
.r4-detail-choice legend{padding:0;margin:0 0 11px;color:#343C33;font-size:13px;font-weight:650}
.r4-detail-skus{display:flex;gap:10px;flex-wrap:wrap}
.r4-detail-skus>button{min-width:108px!important;min-height:58px;padding:10px 14px!important;border:1px solid #E4E1DC!important;border-radius:7px!important;background:#FFF!important;color:#596056!important;text-align:left!important;font-family:inherit!important;font-weight:500!important;font-size:13px!important;cursor:pointer}
.r4-detail-skus>button[aria-pressed="true"]{border-color:#A0021F!important;background:#FCF1F3!important;color:#A0021F!important;box-shadow:inset 0 0 0 .5px #A0021F}
.r4-detail-skus>button>span{display:block;margin-top:5px;font:600 12px Arial,'PingFang SC',sans-serif;opacity:.7}
.r4-detail-weight-note{display:flex;gap:8px;align-items:flex-start;margin:0;padding:11px 12px;border-radius:6px;background:#F7F7F4;color:#767C70;font-size:11px;line-height:1.8}
.r4-detail-weight-note svg{flex:none;margin-top:3px;color:#9C5D63}
.r4-detail-delivery{display:grid;grid-template-columns:64px minmax(0,1fr);gap:12px;align-items:start;padding:15px 0;border-top:1px solid #EEECE8;border-bottom:1px solid #EEECE8}
.r4-detail-delivery>span{padding-top:1px;color:#343C33;font-size:13px;font-weight:650}
.r4-detail-delivery .fm-slots{font-size:12px;color:#727B71;line-height:1.8}
.r4-detail-buy-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.r4-detail-quantity{display:flex;height:46px;overflow:hidden;border:1px solid #E1E3DA;border-radius:7px;flex:none}
.r4-detail-quantity>button{width:34px;border:0;background:#F7F7F4;color:#505A4D;font-size:19px;cursor:pointer}
.r4-detail-quantity>button:hover{background:#EFEFEA}
.r4-detail-quantity>span{display:flex;align-items:center;justify-content:center;min-width:36px;box-sizing:border-box;padding:0 7px;background:#FFF;color:#202A25;font:600 14px Arial,'PingFang SC',sans-serif;font-variant-numeric:tabular-nums}
.r4-detail-add,.r4-detail-buy{height:46px;flex:1;min-width:128px;padding:0 19px;border-radius:7px;font-family:inherit;font-weight:650;font-size:14px;cursor:pointer;white-space:nowrap;transition:background .15s,border-color .15s}
.r4-detail-add{border:1px solid #A0021F;background:#A0021F;color:#FFF}
.r4-detail-add:hover{background:#81162B;border-color:#81162B}
.r4-detail-buy{border:1px solid #DFC1C7;background:#FCF1F3;color:#A0021F}
.r4-detail-buy:hover{background:#F6E6E9;border-color:#A0021F}
.r4-detail-add:disabled,.r4-detail-buy:disabled{background:#F0F1EC;border-color:#E4E6DE;color:#9EA596;cursor:not-allowed}
.r4-detail-service-notes{display:flex;align-items:center;gap:17px;flex-wrap:wrap;color:#879182;font-size:10px;line-height:1.8}
.r4-detail-service-notes>span{display:inline-flex;align-items:center;gap:5px}
.r4-detail-service-notes>span::before{content:'✓';color:#9B7376}
.r4-detail-information{margin-top:28px;background:#FFF;border:1px solid #E7E5E0;border-radius:12px;overflow:hidden}
.r4-detail-tabs{display:flex;gap:30px;border-bottom:1px solid #E7E5E0;padding:0 28px;background:#FFFEFC}
.r4-detail-tabs>button{height:55px;padding:0 2px;border:0;border-bottom:2px solid transparent;background:transparent;color:#778078;font-family:inherit;font-weight:500;font-size:14px;cursor:pointer}
.r4-detail-tabs>button[aria-selected="true"]{border-bottom-color:#A0021F;color:#A0021F;font-weight:700}
.r4-detail-tabs>button:hover{color:#A0021F}
.r4-detail-specs{display:grid;grid-template-columns:142px minmax(0,1fr);row-gap:0;margin:0;padding:10px 28px 20px;font-size:13px;line-height:1.8}
.r4-detail-specs dt,.r4-detail-specs dd{padding:15px 0;border-bottom:1px solid #F0EEE9}
.r4-detail-specs dt{color:#879182}
.r4-detail-specs dd{margin:0;color:#3B4639}
.r4-detail-specs dt:last-of-type,.r4-detail-specs dd:last-of-type{border-bottom:0}
@media(max-width:1180px){.r4-detail-main{padding-right:28px;padding-left:28px}.r4-detail-product{padding:24px;gap:28px;grid-template-columns:minmax(0,.95fr) minmax(0,1fr)}.r4-detail-purchase{gap:16px}.r4-detail-purchase h1{font-size:28px}.r4-detail-buy-row{gap:9px}.r4-detail-add,.r4-detail-buy{min-width:112px;padding:0 12px}.r4-detail-image-note{max-width:34em}.r4-detail-price{font-size:33px}.r4-detail-pricing{padding:16px}}
@media(max-width:860px){.r4-detail-main{padding:22px 18px 40px}.r4-detail-product{grid-template-columns:minmax(0,1fr);padding:18px;gap:25px}.r4-detail-image{max-height:560px;aspect-ratio:1.1}.r4-detail-purchase h1{font-size:27px}.r4-detail-purchase{gap:18px}.r4-detail-image-note{max-width:none}.r4-detail-pricing{padding:17px}.r4-detail-buy-row{gap:10px}.r4-detail-add,.r4-detail-buy{min-width:100px;padding:0 12px}.r4-detail-tabs{padding:0 18px;gap:24px}.r4-detail-tabs>button{font-size:13px}.r4-detail-specs{grid-template-columns:90px minmax(0,1fr);padding:7px 18px 15px;font-size:12px}.r4-detail-information{margin-top:20px}}

Checkout.css:
.r4-checkout-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:6px 0 27px}.r4-checkout-heading h1{font-size:30px;font-weight:600;letter-spacing:-.025em;margin:8px 0}.r4-checkout-heading p{font-size:12px;color:#858A7F;margin:0}.r4-checkout-steps{display:flex;list-style:none;padding:0;margin:0;gap:24px;font-size:11px;color:#8D9186}.r4-checkout-steps li{display:flex;align-items:center;gap:9px}.r4-checkout-steps b{width:23px;height:23px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#EDEEE7;font-size:10px}.r4-checkout-steps li[aria-current="step"]{color:#A0021F;font-weight:600}.r4-checkout-steps li[aria-current="step"] b{background:#A0021F;color:white}
.r4-checkout-layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:23px;align-items:start}.r4-checkout-content{min-width:0;display:flex;flex-direction:column;gap:18px}.r4-checkout-section{background:#FFF;border:1px solid #E6E7DF;border-radius:12px;padding:25px;min-width:0}.r4-checkout-section h2{font-size:17px;font-weight:600;margin:0}.r4-checkout-section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.r4-checkout-section-head a{font-size:11px;color:#A0021F;text-decoration:none}.r4-checkout-section-head span{font-size:10px;color:#919589}.r4-addresses{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.r4-address-option{min-width:0;min-height:99px;border-radius:9px!important;padding:15px!important;line-height:1.7;box-shadow:none}.r4-address-option>strong{display:flex;gap:10px;align-items:center;font-weight:600}.r4-address-option small{font-size:11px;font-weight:400;color:#858B7D}.r4-address-option em{font-size:9px;font-style:normal;background:#FCF1F3;color:#A0021F;padding:2px 5px}.r4-address-option>span{font-size:12px;color:#6B7267}.r4-add-address{padding:18px;background:#FCFCFA;border:1px dashed #D0D4C8;color:#7C8275;border-radius:9px;min-height:99px}.r4-checkout-days{display:flex;gap:9px;margin-bottom:14px;flex-wrap:wrap}.r4-checkout-slots{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.r4-checkout-slots button{border-radius:8px!important;min-width:0;line-height:1.7}.r4-checkout-slots strong{font-size:17px;font-weight:600;white-space:nowrap}.r4-checkout-slots small{font-size:10px;line-height:1.7;text-align:left}.r4-checkout-date-note{font-size:10px;color:#8E9387;line-height:1.8;margin:14px 0 0}.r4-checkout-line{display:grid;grid-template-columns:60px minmax(0,1fr) 86px 67px 84px;gap:13px;align-items:center;padding:16px 0;border-top:1px solid #EEF0E9;min-width:0}.r4-checkout-line>img{width:60px;height:64px;border-radius:7px;object-fit:cover}.r4-checkout-line>div{min-width:0;display:flex;flex-direction:column;gap:5px}.r4-checkout-line h3{font-size:13px;font-weight:600;line-height:1.6;margin:0}.r4-checkout-line p{font-size:10px;line-height:1.6;color:#8B9183;margin:0}.r4-checkout-line em{font-size:10px;font-style:normal;color:#9C6E3C}.r4-checkout-line>span{font-size:12px;text-align:right;line-height:1.8;font-variant-numeric:tabular-nums}.r4-checkout-line del{font-size:10px;color:#A1A697;display:block}.r4-checkout-line>strong{text-align:right;font-size:16px;font-weight:600}.r4-coupon-choices{display:flex;gap:9px;flex-wrap:wrap;margin-top:17px}.r4-coupon-choices button{background:#FFF9FA;border:1px solid #EAD0D7;color:#A0021F;border-radius:7px;padding:12px 14px;font-size:12px;line-height:1.5}.r4-order-note{display:flex;flex-direction:column;gap:10px;margin-top:25px;font-size:12px;font-weight:600}.r4-order-note input{min-height:40px;border:1px solid #DDDFD4;border-radius:6px;padding:0 12px;background:#FCFCFA;outline-color:#A0021F;font-weight:400;font-size:12px;min-width:0;width:100%}
.r4-checkout-summary{position:sticky;top:20px;min-width:0}.r4-checkout-summary-card{background:#FFF;border:1px solid #EAD4D8;border-top:4px solid #A0021F;border-radius:10px;padding:25px}.r4-checkout-summary-card h2{font-size:18px;margin:0 0 22px;font-weight:600}.r4-summary-rows{display:flex;flex-direction:column;gap:14px}.r4-summary-rows>div{display:flex;justify-content:space-between;gap:15px;font-size:12px;color:#787F71}.r4-summary-rows>div span:last-child{color:#38422F}.r4-freight-note{font-size:11px;background:#F4F6EE;color:#737F60;padding:10px 11px;border-radius:5px;line-height:1.7;margin:19px 0}.r4-checkout-total{border-top:1px solid #EAECE2;padding-top:19px;display:flex;justify-content:space-between;align-items:baseline;gap:12px}.r4-checkout-total>span{font-size:13px}.r4-checkout-total strong{color:#A0021F;font-size:33px;font-variant-numeric:tabular-nums;letter-spacing:-.035em;font-weight:600}.r4-summary-address{font-size:10px;line-height:1.9;color:#8D9385;margin:17px 0}.r4-place-order{background:#A0021F;color:#FFF;border:0;border-radius:6px;min-height:46px;font-size:14px;font-weight:600;width:100%}.r4-place-order:hover{background:#81162B}.r4-sandbox-note{font-size:9px;line-height:1.9;color:#9C9F94;margin:13px 0 0}.r4-weight-note{padding:17px 18px;border:1px solid #E5E1D0;background:#F7F6EF;color:#8C8064;font-size:11px;line-height:1.9;border-radius:8px;margin-top:14px}.r4-weight-note strong{display:block;color:#665D49;font-size:12px;margin-bottom:5px}
@media(max-width:1150px){.r4-checkout-layout{grid-template-columns:minmax(0,1fr) 300px;gap:18px}.r4-checkout-section{padding:20px}.r4-checkout-slots{grid-template-columns:1fr}.r4-checkout-slots button{flex-direction:row!important;justify-content:space-between;gap:12px!important;align-items:center!important}.r4-checkout-line{grid-template-columns:52px minmax(0,1fr) 65px 58px 69px;gap:10px}.r4-checkout-line>img{width:52px;height:58px}.r4-checkout-summary-card{padding:22px}.r4-checkout-steps{gap:16px;font-size:10px}}
