@media(max-width:600px){.r4-checkout-heading{display:block;margin-bottom:23px}.r4-checkout-heading h1{font-size:27px}.r4-checkout-heading p{font-size:10px}.r4-checkout-steps{margin-top:20px;justify-content:space-between;font-size:9px;gap:7px}.r4-checkout-steps li{gap:6px}.r4-checkout-steps b{width:20px;height:20px}.r4-checkout-section{padding:17px}.r4-checkout-section h2{font-size:16px}.r4-checkout-section-head{flex-wrap:wrap}.r4-checkout-slots{grid-template-columns:1fr}.r4-checkout-slots button{flex-direction:row!important;align-items:center!important}.r4-checkout-line{grid-template-columns:48px minmax(0,1fr) 48px 63px;gap:8px}.r4-checkout-line .r4-line-unit{display:none}.r4-checkout-line>img{width:48px;height:52px}.r4-checkout-line h3{font-size:12px}.r4-checkout-line p{font-size:9px}.r4-checkout-line>strong{font-size:14px}.r4-checkout-total strong{font-size:30px}}
